import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom input sanitizer - strips common attack patterns
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove script tags and event handlers
        input = input.replaceAll("(?i)<script[^>]*>.*?</script>", "");
        input = input.replaceAll("(?i)on\\w+\\s*=", "");
        // Remove comment sequences that could break out of strings
        input = input.replaceAll("/\\*", "").replaceAll("\\*/", "");
        // Limit length
        if (input.length() > 200) input = input.substring(0, 200);
        return input;
    }

    // Validates report type against allowed values
    private boolean isValidReportType(String type) {
        return type != null && type.matches("^(sales|inventory|users|audit)$");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        HttpSession session = req.getSession(false);
        if (session == null || session.getAttribute("userId") == null) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortColumn = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Sanitize user inputs
        dateRange = sanitizeInput(dateRange);
        sortColumn = sanitizeInput(sortColumn);
        filterExpr = sanitizeInput(filterExpr);

        String tableName = "report_" + reportType;

        // Build query with parameterized date range but dynamic sort/filter
        StringBuilder query = new StringBuilder();
        query.append("SELECT * FROM ").append(tableName);
        query.append(" WHERE created_at BETWEEN ? AND ?");

        if (filterExpr != null && !filterExpr.isEmpty()) {
            // Filter expressions like "status=active" or "region=US"
            query.append(" AND ").append(filterExpr);
        }

        if (sortColumn != null && !sortColumn.isEmpty()) {
            query.append(" ORDER BY ").append(sortColumn);
        }

        query.append(" LIMIT 1000");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            String[] dates = parseDateRange(dateRange);
            stmt.setString(1, dates[0]);
            stmt.setString(2, dates[1]);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Log but don't expose internal details
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String[] parseDateRange(String range) {
        if (range == null || !range.contains("|")) {
            return new String[]{"2024-01-01", "2024-12-31"};
        }
        String[] parts = range.split("\\|");
        return new String[]{parts[0].trim(), parts[1].trim()};
    }
}
